// Report account balances from a ledger file.

const encoder = new TextEncoder();

// Parses an unsigned decimal amount with two fraction digits, such as 12.05,
// into an exact count of cents.
function to_cents(amount: string): bigint {
  const [whole, fraction] = amount.split(".");
  return BigInt(whole) * 100n + BigInt(fraction);
}

function format_cents(cents: bigint): string {
  const sign = cents < 0n ? "-" : "";
  const magnitude = cents < 0n ? -cents : cents;
  const fraction = (magnitude % 100n).toString().padStart(2, "0");
  return `${sign}${magnitude / 100n}.${fraction}`;
}

// Compares two strings by their UTF-8 bytes, not by UTF-16 code units.
function compare_bytes(left: string, right: string): number {
  const a = encoder.encode(left);
  const b = encoder.encode(right);
  const common = Math.min(a.length, b.length);
  for (let i = 0; i < common; i++) {
    if (a[i] !== b[i]) {
      return a[i] - b[i];
    }
  }
  return a.length - b.length;
}

function by_balance(left: [string, bigint], right: [string, bigint]): number {
  if (left[1] !== right[1]) {
    return left[1] > right[1] ? -1 : 1;
  }
  return compare_bytes(left[0], right[0]);
}

function read_ledger(path: string): string[][] {
  return Deno.readTextFileSync(path)
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => line !== "")
    .map((line) => line.split(/\s+/));
}

function main() {
  const lines = read_ledger(Deno.args[0]);
  const n = Number(lines[0][1]);

  const balances = new Map<string, bigint>();
  for (let k = 1; k <= n; k++) {
    const [account, kind, amount] = lines[k];
    const sign = kind === "credit" ? 1n : kind === "debit" ? -1n : 0n;
    if (sign === 0n) {
      console.log(`ERROR line ${k}`);
      return;
    }
    const signed = sign * to_cents(amount);
    balances.set(account, (balances.get(account) ?? 0n) + signed);
  }

  const entries = [...balances.entries()].sort(by_balance);
  let total = 0n;
  for (const [account, balance] of entries) {
    console.log(`${account} ${format_cents(balance)}`);
    total += balance;
  }
  console.log(`TOTAL ${format_cents(total)}`);
}

main();

